 const total=Number(row.agree)+Number(row.disagree),agreePct=total?Math.round(Number(row.agree)/total*100):50,previous=communityState.ranks[kind][row.id],rank=index+1,moved=previous&&previous>rank,player=playerFor(row.player),lineup=kind==='lineup';
