 feed.innerHTML=rows.length?rows.map((row,index)=>opinionCard(row,kind,index)).join(''):'<div class="opinion-empty"><div><strong>'+say(kind==='lineup'?'ABRA O DEBATE':'MANDE A PRIMEIRA','START THE DEBATE','ABRE EL DEBATE')+'</strong><span>'+say(kind==='lineup'?'Escolha um jogador e defenda sua escalação.':'A primeira opinião impopular pode ser a sua.',kind==='lineup'?'Pick a player and back your lineup.':'The first unpopular opinion can be yours.',kind==='lineup'?'Elige un jugador y defiende tu alineación.':'La primera opinión impopular puede ser la tuya.')+'</span></div></div>';
